 int type=1,page,generation,epoch=-1,catalogFirst,catalogTop,detailFirst,detailTop,revision,focus;boolean busy,more=true;String query="",error="";PgcModels.Show selected;PgcModels.Season season;Pane pane;
 PgcUi(MainActivity a){this.a=a;}
 void enter(){if(epoch!=a.auth.epoch()){generation++;epoch=a.auth.epoch();busy=false;season=null;if(selected!=null){loadSeason();return;}}redraw();if(selected==null&&page==0&&!busy)loadPage();}
 void redraw(){revision++;if(pane!=null&&pane.isAttachedToWindow())pane.bind();}
 void saveAnchor(){if(pane==null||pane.list.getChildCount()==0)return;if(selected==null){catalogFirst=pane.list.getFirstVisiblePosition();catalogTop=pane.list.getChildAt(0).getTop();}else{detailFirst=pane.list.getFirstVisiblePosition();detailTop=pane.list.getChildAt(0).getTop();}}
 void chooseType(int value){if(value==type&&selected==null&&query.isEmpty()&&page>0)return;type=value;query="";refresh();}
 void refresh(){generation++;busy=false;selected=null;season=null;page=0;items.clear();more=true;error="";focus=catalogFirst=catalogTop=detailFirst=detailTop=0;redraw();loadPage();}
 void loadPage(){if(busy||!more||selected!=null||a.dead)return;busy=true;error="";int token=++generation,auth=a.auth.epoch(),requested=page+1,category=type;String keyword=query;Source service=source;redraw();a.io.execute(()->{PgcModels.Page found=null;String failure="";try{found=service.catalog(category,keyword,requested);}catch(Exception e){failure=message(e);}PgcModels.Page result=found;String problem=failure;a.ui.post(()->{if(a.dead||token!=generation||auth!=a.auth.epoch())return;busy=false;error=problem;if(result!=null){Set<Long> seen=new HashSet<>();for(PgcModels.Show s:items)seen.add(s.id);int before=items.size();for(PgcModels.Show s:result.items)if(seen.add(s.id))items.add(s);page=result.page;more=result.more;if(more&&items.size()==before){more=false;}}saveAnchor();redraw();});});}
