 void loadSeason(){if(selected==null||busy||a.dead)return;busy=true;error="";int token=++generation,auth=a.auth.epoch();long id=selected.id;Source service=source;redraw();a.io.execute(()->{PgcModels.Season found=null;String failure="";try{found=service.season(id);}catch(Exception e){failure=message(e);}PgcModels.Season result=found;String problem=failure;a.ui.post(()->{if(a.dead||token!=generation||auth!=a.auth.epoch()||selected==null||selected.id!=id)return;busy=false;error=problem;season=result;if(result!=null)selected=result.show;redraw();});});}
 void play(Video video){if(busy||video==null)return;saveAnchor();busy=true;error="";int token=++generation,auth=a.auth.epoch();Source service=source;redraw();a.io.execute(()->{StreamSpec found=null;String failure="";try{found=service.stream(video);}catch(Exception e){failure=message(e);}StreamSpec spec=found;String problem=failure;a.ui.post(()->{if(a.dead||token!=generation||auth!=a.auth.epoch())return;busy=false;error=problem;if(spec==null){redraw();return;}if(!a.columnBrowsing())return;video.fullSpec=spec;video.fullSpecAt=System.currentTimeMillis();video.fullQuality=0;video.pgcAuthEpoch=auth;a.playPgcEpisode(video);});});}
 void episodeMenu(Video current){a.features.menu("选集 · "+current.seasonTitle);if(current.pgcEpisodes.isEmpty()){a.features.add("打开作品选集",()->{a.features.close();a.returnToPgc();open(new PgcModels.Show(current.seasonId,1,current.seasonTitle,current.cover,"","","",""));});}else for(Video v:current.pgcEpisodes){a.features.add((v.episodeId==current.episodeId?"正在播放 · ":"")+v.episodeTitle+(v.pgcBadge.isEmpty()?"":"  · "+v.pgcBadge),()->{a.features.close();a.playPgcEpisode(v);});}a.features.add("返回播放",a.features::close);a.features.redraw();}
 boolean back(){if(selected==null){if(!query.isEmpty()){query="";refresh();return true;}return false;}generation++;busy=false;selected=null;season=null;error="";focus=0;redraw();return true;}
 void official(Video v){long ep=v==null?0:v.episodeId;String url="https://www.bilibili.com/bangumi/play/"+(ep>0?"ep"+ep:"ss"+selected.id);try{a.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(ActivityNotFoundException e){a.message("未找到可打开 B站的浏览器");}}
 void search(){a.features.showSystemInput("搜索番剧 / 影视",query,value->{a.features.close();a.channel=a.homeTab=MainActivity.COLUMN;query=value.trim();refresh();a.render(false);});}
 String message(Exception e){return e.getMessage()==null?"加载失败，点击重试":e.getMessage();}
 boolean key(KeyEvent e){int k=e.getKeyCode(),yes=a.abSwap?KeyEvent.KEYCODE_BUTTON_B:KeyEvent.KEYCODE_BUTTON_A,no=a.abSwap?KeyEvent.KEYCODE_BUTTON_A:KeyEvent.KEYCODE_BUTTON_B;boolean nav=k==KeyEvent.KEYCODE_DPAD_LEFT||k==KeyEvent.KEYCODE_DPAD_RIGHT||k==KeyEvent.KEYCODE_DPAD_UP||k==KeyEvent.KEYCODE_DPAD_DOWN;if(!nav&&k!=yes&&k!=no&&k!=KeyEvent.KEYCODE_ENTER&&k!=KeyEvent.KEYCODE_DPAD_CENTER&&k!=KeyEvent.KEYCODE_BACK&&k!=KeyEvent.KEYCODE_ESCAPE)return false;if(e.getAction()!=KeyEvent.ACTION_DOWN)return true;if(k==no||k==KeyEvent.KEYCODE_BACK||k==KeyEvent.KEYCODE_ESCAPE){a.back();return true;}if(nav){move(k==KeyEvent.KEYCODE_DPAD_LEFT?-1:k==KeyEvent.KEYCODE_DPAD_RIGHT?1:k==KeyEvent.KEYCODE_DPAD_UP?-(selected==null&&pane!=null?pane.columns:1):selected==null&&pane!=null?pane.columns:1);return true;}confirm();return true;}
 void move(int delta){int size=selected==null?items.size():season==null?0:season.episodes.size();focus=Math.max(0,Math.min(size-1,focus+delta));if(pane!=null){pane.adapter.notifyDataSetChanged();pane.list.smoothScrollToPosition(selected==null?focus/pane.columns:focus+1);}if(selected==null&&focus>=size-4&&error.isEmpty())loadPage();}
 void confirm(){if(selected==null){if(!items.isEmpty())open(items.get(Math.min(focus,items.size()-1)));else if(!busy)loadPage();}else if(season!=null&&!season.episodes.isEmpty())play(season.episodes.get(Math.min(focus,season.episodes.size()-1)));else if(!busy)loadSeason();}

