  int px(float value){return Math.round(value*unit);}TextView text(String s,float size,int color,boolean bold){TextView v=new TextView(getContext());v.setText(s);v.setTextSize(TypedValue.COMPLEX_UNIT_PX,px(size));v.setTextColor(color);v.setTypeface(bold?Typeface.DEFAULT_BOLD:Typeface.DEFAULT);v.setIncludeFontPadding(false);v.setLineSpacing(px(3),1);return v;}
