  @Override protected void onSizeChanged(int w,int h,int ow,int oh){super.onSizeChanged(w,h,ow,oh);saveAnchor();unit=Math.max(.6f,Math.min(w,h)/480f);columns=w>h?4:2;bound=-1;post(this::bind);}
