    LinearLayout row=new LinearLayout(getContext());for(int col=0;col<gridColumns;col++){int index=position*gridColumns+col;LinearLayout card=new LinearLayout(getContext());card.setOrientation(VERTICAL);card.setPadding(px(8),px(8),px(8),px(14));row.addView(card,new LayoutParams(0,-2,1));if(index>=rows.size())continue;PgcModels.Show show=rows.get(index);int width=Math.max(1,(getWidth()-px(24))/gridColumns-px(16));Poster poster=new Poster(show);card.addView(poster,new LayoutParams(-1,Math.round(width*1.32f)));TextView title=text(show.title,16,a.ink,true);title.setMaxLines(2);title.setMinLines(2);title.setEllipsize(TextUtils.TruncateAt.END);title.setPadding(0,px(10),0,px(6));card.addView(title);TextView caption=text(show.update+(show.score.isEmpty()?"":" · "+show.score+"分"),12,a.muted,false);caption.setSingleLine(true);caption.setEllipsize(TextUtils.TruncateAt.END);card.addView(caption);card.setContentDescription("查看作品："+show.title);card.setBackground(UiStyle.ripple(getContext(),index==focus?UiStyle.ACCENT_FILL:Color.WHITE,UiStyle.RADIUS_CONTROL));card.setOnClickListener(v->{focus=index;open(show);});UiStyle.pressFeedback(card);}return row;
